static PcoSemaphore startWall(0);

void worker(int id) {
    startWall.acquire(); // Wait until main() opens the gate
    // Safe: all threads[0..N-1] are non-null!
}

int main() {
    for (unsigned int i = 0; i < N; i++) {
        threads[i] = new PcoThread(worker, i);
    }
    // All threads created -> open the starting wall:
    for (unsigned int i = 0; i < N; i++) {
        startWall.release();
    }
    for (unsigned int i = 0; i < N; i++) {
        threads[i]->join();
        delete threads[i];
    }
}

void lockPair(Player* a, Player* b) {
    if (a == b) {
        a->mutex.lock(); // or a->sem.acquire()
        return;
    }
    if (a->id < b->id) {
        a->mutex.lock();
        b->mutex.lock();
    } else {
        b->mutex.lock();
        a->mutex.lock();
    }
}

void unlockPair(Player* a, Player* b) {
    if (a == b) {
        a->mutex.unlock(); // CRITICAL: only release once!
        return;
    }
    a->mutex.unlock();
    b->mutex.unlock();
}

